# Descripción completa de cada escuela (hanafí, shafi'í, hanbalí) para cada punto con diferencias.
# La descripción malikí es el texto principal de cada tarjeta en guia_data.py.
# Formato: título árabe exacto -> {escuela: (árabe, español)}

M = {
'أَحْكَامُ الْأَفْعَالِ': {
 'hanafi': ("• الْفَرْضُ: مَا ثَبَتَ بِدَلِيلٍ قَطْعِيٍّ، وَلَا تَصِحُّ الْعِبَادَةُ بِدُونِهِ.\n• الْوَاجِبُ: مَا ثَبَتَ بِدَلِيلٍ ظَنِّيٍّ، يَأْثَمُ تَارِكُهُ عَمْدًا، وَإِذَا تُرِكَ سَهْوًا فِي الصَّلَاةِ جُبِرَ بِسُجُودِ السَّهْوِ.\n• السُّنَّةُ الْمُؤَكَّدَةُ: يُثَابُ فَاعِلُهَا وَيُلَامُ تَارِكُهَا.\n• الْمَنْدُوبُ: يُثَابُ فَاعِلُهُ وَلَا يُلَامُ تَارِكُهُ.\n• الْمَكْرُوهُ: تَحْرِيمًا (قَرِيبٌ مِنَ الْحَرَامِ) أَوْ تَنْزِيهًا (الْأَوْلَى تَرْكُهُ).",
            "• Farḍ: lo probado con una prueba definitiva; sin él, el acto de adoración no es válido.\n• Wāŷib: lo probado con una prueba no definitiva; quien lo deja a propósito peca, y si se omite por olvido en la oración se compensa con la postración del olvido.\n• Sunna confirmada: se recompensa a quien la hace y se reprocha a quien la deja.\n• Mandūb (recomendado): se recompensa a quien lo hace y no se reprocha a quien lo deja.\n• Makrūh: puede ser cercano a lo prohibido (taḥrīman) o simplemente preferible dejarlo (tanzīhan)."),
 'shafii': ("• الرُّكْنُ (الْفَرْضُ): لَا تَصِحُّ الصَّلَاةُ بِدُونِهِ، وَلَا يُجْبَرُ بِالسُّجُودِ.\n• السُّنَنُ قِسْمَانِ:\n  - الْأَبْعَاضُ: كَالتَّشَهُّدِ الْأَوَّلِ وَالْقُنُوتِ، يُسْجَدُ لِتَرْكِهَا.\n  - الْهَيْئَاتُ: كَالتَّكْبِيرَاتِ وَالتَّسْبِيحِ وَالسُّورَةِ، لَا يُسْجَدُ لِتَرْكِهَا.\n• الْمَكْرُوهُ: يُثَابُ تَارِكُهُ وَلَا يُعَاقَبُ فَاعِلُهُ.\n• الْفَرْضُ وَالْوَاجِبُ عِنْدَهُمْ بِمَعْنًى وَاحِدٍ.",
            "• Rukn (pilar, farḍ): sin él la oración no es válida, y no se compensa con la postración.\n• Las sunnas son de dos tipos:\n  - Abʿāḍ: como el primer tashahhud o el qunūt; si se omiten, se hace la postración del olvido.\n  - Hayʾāt: como los takbīr, la glorificación o la sura; si se omiten, no se hace la postración.\n• Makrūh: se recompensa a quien lo deja y no se castiga a quien lo hace.\n• Farḍ y wāŷib significan lo mismo para ellos."),
 'hanbali': ("• الرُّكْنُ: لَا يَسْقُطُ عَمْدًا وَلَا سَهْوًا، وَلَا تَصِحُّ الصَّلَاةُ بِدُونِهِ.\n• الْوَاجِبُ: تَبْطُلُ الصَّلَاةُ بِتَرْكِهِ عَمْدًا، وَيُجْبَرُ بِسُجُودِ السَّهْوِ إِنْ تُرِكَ سَهْوًا، كَتَكْبِيرَاتِ الِانْتِقَالِ وَالتَّسْبِيحِ وَالتَّشَهُّدِ الْأَوَّلِ.\n• السُّنَّةُ: لَا تَبْطُلُ الصَّلَاةُ بِتَرْكِهَا، وَلَا يَجِبُ لَهَا سُجُودٌ.\n• الْمَكْرُوهُ: يُثَابُ تَارِكُهُ وَلَا يُعَاقَبُ فَاعِلُهُ.",
            "• Rukn (pilar): no se puede omitir ni a propósito ni por olvido; sin él la oración no es válida.\n• Wāŷib: dejarlo a propósito invalida la oración; si se omite por olvido se compensa con la postración, como los takbīr de transición, la glorificación o el primer tashahhud.\n• Sunna: omitirla no invalida la oración ni obliga a postrarse.\n• Makrūh: se recompensa a quien lo deja y no se castiga a quien lo hace."),
},
'فَرَائِضُ الْوُضُوءِ (سَبْعٌ)': {
 'hanafi': ("الْفَرَائِضُ أَرْبَعٌ:\n١. غَسْلُ الْوَجْهِ.\n٢. غَسْلُ الْيَدَيْنِ مَعَ الْمِرْفَقَيْنِ.\n٣. مَسْحُ رُبُعِ الرَّأْسِ.\n٤. غَسْلُ الرِّجْلَيْنِ مَعَ الْكَعْبَيْنِ.\nأَمَّا النِّيَّةُ وَالتَّسْمِيَةُ وَالتَّرْتِيبُ وَالْمُوَالَاةُ فَسُنَنٌ، وَلَا يُشْتَرَطُ الدَّلْكُ.",
            "Los actos obligatorios son cuatro:\n1. Lavar la cara.\n2. Lavar las manos y los brazos con los codos.\n3. Pasar la mano mojada por un cuarto de la cabeza.\n4. Lavar los pies con los tobillos.\nLa intención, decir «Bismillāh», el orden y la continuidad son sunna, y frotar no es condición."),
 'shafii': ("الْفَرَائِضُ سِتٌّ:\n١. النِّيَّةُ عِنْدَ غَسْلِ الْوَجْهِ.\n٢. غَسْلُ الْوَجْهِ.\n٣. غَسْلُ الْيَدَيْنِ مَعَ الْمِرْفَقَيْنِ.\n٤. مَسْحُ بَعْضِ الرَّأْسِ وَلَوْ شَعْرَةً.\n٥. غَسْلُ الرِّجْلَيْنِ مَعَ الْكَعْبَيْنِ.\n٦. التَّرْتِيبُ.\nأَمَّا الْمُوَالَاةُ وَالدَّلْكُ فَسُنَّةٌ.",
            "Los actos obligatorios son seis:\n1. La intención, al lavar la cara.\n2. Lavar la cara.\n3. Lavar las manos y los brazos con los codos.\n4. Pasar la mano mojada por una parte de la cabeza, aunque sea un pelo.\n5. Lavar los pies con los tobillos.\n6. El orden.\nLa continuidad y el frotar son sunna."),
 'hanbali': ("الْفَرَائِضُ سِتٌّ:\n١. غَسْلُ الْوَجْهِ، وَمِنْهُ الْمَضْمَضَةُ وَالِاسْتِنْشَاقُ.\n٢. غَسْلُ الْيَدَيْنِ مَعَ الْمِرْفَقَيْنِ.\n٣. مَسْحُ الرَّأْسِ كُلِّهِ، وَمِنْهُ الْأُذُنَانِ.\n٤. غَسْلُ الرِّجْلَيْنِ مَعَ الْكَعْبَيْنِ.\n٥. التَّرْتِيبُ.\n٦. الْمُوَالَاةُ.\nوَالنِّيَّةُ شَرْطٌ، وَالتَّسْمِيَةُ وَاجِبَةٌ مَعَ الذِّكْرِ.",
            "Los actos obligatorios son seis:\n1. Lavar la cara, que incluye enjuagar la boca y la nariz.\n2. Lavar las manos y los brazos con los codos.\n3. Pasar la mano mojada por toda la cabeza, incluidas las orejas.\n4. Lavar los pies con los tobillos.\n5. El orden.\n6. La continuidad.\nLa intención es condición, y decir «Bismillāh» es obligatorio si uno se acuerda."),
},
'سُنَنُ الْوُضُوءِ وَفَضَائِلُهُ': {
 'hanafi': ("مِنْ سُنَنِ الْوُضُوءِ: النِّيَّةُ، التَّسْمِيَةُ، غَسْلُ الْيَدَيْنِ إِلَى الرُّسْغَيْنِ، السِّوَاكُ، الْمَضْمَضَةُ، الِاسْتِنْشَاقُ، تَخْلِيلُ اللِّحْيَةِ وَالْأَصَابِعِ، تَثْلِيثُ الْغَسْلِ، اسْتِيعَابُ الرَّأْسِ بِالْمَسْحِ مَرَّةً، مَسْحُ الْأُذُنَيْنِ بِمَاءِ الرَّأْسِ، التَّرْتِيبُ، وَالْمُوَالَاةُ.\nوَمِنَ الْمُسْتَحَبَّاتِ: التَّيَامُنُ، وَمَسْحُ الرَّقَبَةِ، وَالذِّكْرُ بَعْدَهُ.",
            "Sunna: la intención, decir «Bismillāh», lavar las manos hasta las muñecas, el siwāk, enjuagar la boca y la nariz, pasar el agua entre la barba y entre los dedos, lavar cada parte tres veces, pasar la mano por toda la cabeza una vez, pasar las manos por las orejas con el agua de la cabeza, el orden y la continuidad.\nRecomendado: empezar por la derecha, pasar la mano por la nuca y el dhikr al terminar."),
 'shafii': ("مِنْ سُنَنِ الْوُضُوءِ: السِّوَاكُ، التَّسْمِيَةُ، غَسْلُ الْكَفَّيْنِ، الْمَضْمَضَةُ وَالِاسْتِنْشَاقُ، تَثْلِيثُ الْغَسْلِ وَالْمَسْحِ، مَسْحُ جَمِيعِ الرَّأْسِ، مَسْحُ الْأُذُنَيْنِ بِمَاءٍ جَدِيدٍ، تَخْلِيلُ اللِّحْيَةِ الْكَثَّةِ وَالْأَصَابِعِ، التَّيَامُنُ، الْمُوَالَاةُ، الدَّلْكُ، وَالذِّكْرُ بَعْدَهُ.",
            "Sunna: el siwāk, decir «Bismillāh», lavar las manos, enjuagar la boca y la nariz, repetir tres veces cada lavado y el paso de la mano por la cabeza, pasar la mano por toda la cabeza, pasar las manos por las orejas con agua nueva, pasar el agua entre la barba espesa y entre los dedos, empezar por la derecha, la continuidad, frotar y el dhikr al terminar."),
 'hanbali': ("مِنْ سُنَنِ الْوُضُوءِ: السِّوَاكُ، غَسْلُ الْكَفَّيْنِ ثَلَاثًا، الْبَدَاءَةُ بِالْمَضْمَضَةِ وَالِاسْتِنْشَاقِ وَالْمُبَالَغَةُ فِيهِمَا لِغَيْرِ الصَّائِمِ، تَخْلِيلُ اللِّحْيَةِ الْكَثِيفَةِ وَالْأَصَابِعِ، التَّيَامُنُ، وَالْغَسْلَةُ الثَّانِيَةُ وَالثَّالِثَةُ.\nأَمَّا التَّسْمِيَةُ فَوَاجِبَةٌ مَعَ الذِّكْرِ، وَالْمَضْمَضَةُ وَالِاسْتِنْشَاقُ وَاجِبَانِ لِأَنَّهُمَا مِنَ الْوَجْهِ، وَالتَّرْتِيبُ فَرْضٌ.",
            "Sunna: el siwāk, lavar las manos tres veces, empezar enjuagando la boca y la nariz y hacerlo a fondo (salvo quien ayuna), pasar el agua entre la barba espesa y entre los dedos, empezar por la derecha y lavar una segunda y una tercera vez.\nDecir «Bismillāh» es obligatorio si uno se acuerda; enjuagar la boca y la nariz es obligatorio porque forman parte de la cara; y el orden es obligatorio."),
},
'٥. مَسْحُ الرَّأْسِ': {
 'hanafi': ("الْفَرْضُ مَسْحُ رُبُعِ الرَّأْسِ مَرَّةً وَاحِدَةً، وَالسُّنَّةُ اسْتِيعَابُهُ كُلِّهِ مَرَّةً: يَبْدَأُ مِنْ مُقَدَّمِهِ إِلَى قَفَاهُ، ثُمَّ يَمْسَحُ أُذُنَيْهِ بِمَاءِ الرَّأْسِ.",
            "Lo obligatorio es pasar la mano mojada por un cuarto de la cabeza, una vez. La sunna es pasarla por toda la cabeza una vez, de la frente a la nuca, y luego pasar las manos por las orejas con la misma agua de la cabeza."),
 'shafii': ("الْفَرْضُ مَسْحُ بَعْضِ الرَّأْسِ وَلَوْ شَعْرَةً وَاحِدَةً، وَالسُّنَّةُ اسْتِيعَابُهُ وَتَثْلِيثُ الْمَسْحِ، ثُمَّ مَسْحُ الْأُذُنَيْنِ بِمَاءٍ جَدِيدٍ.",
            "Lo obligatorio es pasar la mano mojada por una parte de la cabeza, aunque sea un solo pelo. La sunna es pasarla por toda la cabeza y repetirlo tres veces, y después pasar las manos por las orejas con agua nueva."),
 'hanbali': ("الْفَرْضُ مَسْحُ جَمِيعِ الرَّأْسِ مَرَّةً وَاحِدَةً مَعَ الْأُذُنَيْنِ: يَبْدَأُ مِنْ مُقَدَّمِهِ إِلَى قَفَاهُ ثُمَّ يَرُدُّ يَدَيْهِ إِلَى حَيْثُ بَدَأَ، وَلَا يُسَنُّ تَكْرَارُ الْمَسْحِ.",
            "Lo obligatorio es pasar la mano mojada por toda la cabeza una vez, junto con las orejas: de la frente a la nuca y vuelta al punto de partida. No es sunna repetirlo."),
},
'نَوَاقِضُ الْوُضُوءِ': {
 'hanafi': ("يَنْقُضُ الْوُضُوءَ:\n• كُلُّ مَا خَرَجَ مِنَ السَّبِيلَيْنِ.\n• الدَّمُ أَوِ الْقَيْحُ إِذَا سَالَ عَنْ مَوْضِعِهِ.\n• الْقَيْءُ مِلْءَ الْفَمِ.\n• النَّوْمُ مُضْطَجِعًا أَوْ مُتَّكِئًا.\n• زَوَالُ الْعَقْلِ بِإِغْمَاءٍ أَوْ سُكْرٍ أَوْ جُنُونٍ.\n• الْقَهْقَهَةُ فِي صَلَاةٍ ذَاتِ رُكُوعٍ وَسُجُودٍ.\nوَلَا يَنْقُضُهُ مَسُّ الذَّكَرِ، وَلَا لَمْسُ الْمَرْأَةِ، وَلَا أَكْلُ لَحْمِ الْإِبِلِ.",
            "Anulan el wudu:\n• Todo lo que sale por las dos vías naturales.\n• La sangre o el pus cuando fluye fuera de su sitio.\n• Vomitar a boca llena.\n• Dormir tumbado o recostado.\n• Perder la consciencia por desmayo, embriaguez o locura.\n• Reírse a carcajadas en una oración con inclinación y postración.\nNo lo anulan tocar el pene, tocar a una mujer ni comer carne de camello."),
 'shafii': ("يَنْقُضُ الْوُضُوءَ:\n• الْخَارِجُ مِنَ السَّبِيلَيْنِ، إِلَّا الْمَنِيَّ.\n• زَوَالُ الْعَقْلِ، إِلَّا نَوْمَ مَنْ مَكَّنَ مَقْعَدَتَهُ مِنَ الْأَرْضِ.\n• لَمْسُ بَشَرَةِ الْمَرْأَةِ الْأَجْنَبِيَّةِ بِلَا حَائِلٍ، وَلَوْ بِغَيْرِ شَهْوَةٍ.\n• مَسُّ الْقُبُلِ أَوِ الدُّبُرِ بِبَاطِنِ الْكَفِّ.\nوَلَا يَنْقُضُهُ الدَّمُ وَلَا الْقَيْءُ وَلَا أَكْلُ لَحْمِ الْإِبِلِ.",
            "Anulan el wudu:\n• Lo que sale por las dos vías naturales, salvo el semen.\n• Perder la consciencia, salvo el sueño de quien está bien sentado en el suelo.\n• Tocar sin barrera la piel de una mujer no maḥram, aunque sea sin deseo.\n• Tocar las partes íntimas con la palma de la mano.\nNo lo anulan la sangre, el vómito ni comer carne de camello."),
 'hanbali': ("يَنْقُضُ الْوُضُوءَ:\n• الْخَارِجُ مِنَ السَّبِيلَيْنِ.\n• الْخَارِجُ النَّجِسُ الْكَثِيرُ مِنْ سَائِرِ الْبَدَنِ.\n• زَوَالُ الْعَقْلِ، إِلَّا يَسِيرَ نَوْمٍ مِنْ جَالِسٍ أَوْ قَائِمٍ.\n• مَسُّ الْفَرْجِ بِالْيَدِ بِلَا حَائِلٍ.\n• لَمْسُ الْمَرْأَةِ بِشَهْوَةٍ.\n• غَسْلُ الْمَيِّتِ.\n• أَكْلُ لَحْمِ الْإِبِلِ.\n• الرِّدَّةُ.",
            "Anulan el wudu:\n• Lo que sale por las dos vías naturales.\n• Una impureza abundante que sale de cualquier otra parte del cuerpo.\n• Perder la consciencia, salvo un sueño ligero sentado o de pie.\n• Tocar las partes íntimas con la mano sin barrera.\n• Tocar a una mujer con deseo.\n• Lavar a un difunto.\n• Comer carne de camello.\n• La apostasía."),
},
'مُوجِبَاتُ الْغُسْلِ': {
 'hanafi': ("يَجِبُ الْغُسْلُ بِـ:\n١. خُرُوجِ الْمَنِيِّ بِشَهْوَةٍ.\n٢. الْتِقَاءِ الْخِتَانَيْنِ وَلَوْ بِغَيْرِ إِنْزَالٍ.\n٣. انْقِطَاعِ الْحَيْضِ.\n٤. انْقِطَاعِ النِّفَاسِ.\nوَيَجِبُ عَلَى الْأَحْيَاءِ غُسْلُ الْمَيِّتِ الْمُسْلِمِ. وَمَنْ أَسْلَمَ يَجِبُ عَلَيْهِ الْغُسْلُ إِنْ كَانَ جُنُبًا، وَإِلَّا اسْتُحِبَّ.",
            "El ghusl es obligatorio por:\n1. La salida de semen con deseo.\n2. La relación sexual, aunque no haya eyaculación.\n3. El fin de la menstruación.\n4. El fin del sangrado posparto.\nLos vivos deben lavar al musulmán fallecido. Quien entra en el islam debe hacer ghusl si estaba en ŷanāba; si no, es recomendable."),
 'shafii': ("يَجِبُ الْغُسْلُ بِـ:\n١. خُرُوجِ الْمَنِيِّ وَلَوْ بِغَيْرِ شَهْوَةٍ.\n٢. الْتِقَاءِ الْخِتَانَيْنِ.\n٣. الْحَيْضِ.\n٤. النِّفَاسِ.\n٥. الْوِلَادَةِ.\n٦. الْمَوْتِ.\nوَيُسْتَحَبُّ لِمَنْ أَسْلَمَ إِنْ لَمْ يَكُنْ جُنُبًا.",
            "El ghusl es obligatorio por:\n1. La salida de semen, aunque sea sin deseo.\n2. La relación sexual.\n3. La menstruación.\n4. El sangrado posparto.\n5. El parto.\n6. La muerte.\nEs recomendable para quien entra en el islam si no estaba en ŷanāba."),
 'hanbali': ("يَجِبُ الْغُسْلُ بِـ:\n١. خُرُوجِ الْمَنِيِّ بِلَذَّةٍ.\n٢. الْتِقَاءِ الْخِتَانَيْنِ.\n٣. إِسْلَامِ الْكَافِرِ، مُطْلَقًا.\n٤. الْحَيْضِ.\n٥. النِّفَاسِ.\n٦. الْمَوْتِ.",
            "El ghusl es obligatorio por:\n1. La salida de semen con placer.\n2. La relación sexual.\n3. La entrada en el islam, en todo caso.\n4. La menstruación.\n5. El sangrado posparto.\n6. La muerte."),
},
'فَرَائِضُ الْغُسْلِ وَسُنَنُهُ': {
 'hanafi': ("الْفَرَائِضُ ثَلَاثٌ: الْمَضْمَضَةُ، وَالِاسْتِنْشَاقُ، وَغَسْلُ سَائِرِ الْبَدَنِ.\nوَمِنَ السُّنَنِ: النِّيَّةُ، وَالتَّسْمِيَةُ، وَغَسْلُ الْيَدَيْنِ وَالْفَرْجِ أَوَّلًا، وَالْوُضُوءُ قَبْلَهُ، وَالدَّلْكُ، وَتَثْلِيثُ الْغَسْلِ.",
            "Lo obligatorio son tres cosas: enjuagar la boca, enjuagar la nariz y lavar todo el cuerpo.\nSunna: la intención, decir «Bismillāh», lavar primero las manos y las partes íntimas, hacer el wudu antes, frotar y lavar tres veces."),
 'shafii': ("الْفَرَائِضُ: النِّيَّةُ، وَتَعْمِيمُ الْبَدَنِ بِالْمَاءِ بَشَرًا وَشَعْرًا.\nوَمِنَ السُّنَنِ: التَّسْمِيَةُ، وَالْوُضُوءُ قَبْلَهُ، وَالْمَضْمَضَةُ وَالِاسْتِنْشَاقُ، وَالدَّلْكُ، وَالتَّثْلِيثُ، وَالْبَدْءُ بِالْأَيْمَنِ.",
            "Lo obligatorio es la intención y que el agua llegue a todo el cuerpo, piel y pelo.\nSunna: decir «Bismillāh», hacer el wudu antes, enjuagar la boca y la nariz, frotar, lavar tres veces y empezar por la derecha."),
 'hanbali': ("النِّيَّةُ شَرْطٌ، وَالتَّسْمِيَةُ وَاجِبَةٌ مَعَ الذِّكْرِ، وَالْوَاجِبُ تَعْمِيمُ الْبَدَنِ بِالْمَاءِ مَعَ الْمَضْمَضَةِ وَالِاسْتِنْشَاقِ.\nوَمِنَ السُّنَنِ: الْوُضُوءُ قَبْلَهُ، وَالدَّلْكُ، وَالْبَدْءُ بِالْأَيْمَنِ، وَتَثْلِيثُ الْإِفَاضَةِ عَلَى الرَّأْسِ.",
            "La intención es condición y decir «Bismillāh» es obligatorio si uno se acuerda. Lo obligatorio es que el agua llegue a todo el cuerpo, enjuagando también la boca y la nariz.\nSunna: hacer el wudu antes, frotar, empezar por la derecha y echar agua tres veces sobre la cabeza."),
},
'مَتَى يُشْرَعُ التَّيَمُّمُ؟': {
 'hanafi': ("يَتَيَمَّمُ مَنْ عَدِمَ الْمَاءَ أَوْ كَانَ بَعِيدًا عَنْهُ نَحْوَ مِيلٍ، أَوْ خَافَ بِاسْتِعْمَالِهِ مَرَضًا أَوْ زِيَادَتَهُ. وَيَصِحُّ بِكُلِّ مَا كَانَ مِنْ جِنْسِ الْأَرْضِ: التُّرَابِ وَالرَّمْلِ وَالْحَجَرِ وَنَحْوِهَا.",
            "Hace tayammum quien no tiene agua o está lejos de ella (aproximadamente una milla), o teme enfermar o empeorar si la usa. Vale todo lo que es de la naturaleza del suelo: tierra, arena, piedra y similares."),
 'shafii': ("يَتَيَمَّمُ مَنْ فَقَدَ الْمَاءَ بَعْدَ طَلَبِهِ، أَوْ خَافَ بِاسْتِعْمَالِهِ مَرَضًا أَوْ زِيَادَتَهُ أَوْ تَأَخُّرَ بُرْئِهِ. وَلَا يَصِحُّ إِلَّا بِتُرَابٍ طَاهِرٍ لَهُ غُبَارٌ.",
            "Hace tayammum quien no encuentra agua después de buscarla, o teme enfermar, empeorar o tardar en curarse si la usa. Solo vale tierra limpia con polvo."),
 'hanbali': ("يَتَيَمَّمُ مَنْ عَدِمَ الْمَاءَ، أَوْ خَافَ بِاسْتِعْمَالِهِ ضَرَرًا فِي بَدَنِهِ، أَوْ خَافَ عَطَشًا. وَلَا يَصِحُّ إِلَّا بِتُرَابٍ طَهُورٍ لَهُ غُبَارٌ يَعْلَقُ بِالْيَدِ.",
            "Hace tayammum quien no tiene agua, o teme que usarla le haga daño, o que le falte para beber. Solo vale tierra pura con polvo que se pegue a la mano."),
},
'صِفَةُ التَّيَمُّمِ': {
 'hanafi': ("١. النِّيَّةُ.\n٢. يَضْرِبُ بِيَدَيْهِ الصَّعِيدَ ضَرْبَةً وَيَمْسَحُ بِهِمَا وَجْهَهُ.\n٣. يَضْرِبُ ضَرْبَةً ثَانِيَةً وَيَمْسَحُ يَدَيْهِ إِلَى الْمِرْفَقَيْنِ.\nوَالضَّرْبَتَانِ وَاجِبَتَانِ، وَيَصِحُّ التَّيَمُّمُ قَبْلَ دُخُولِ الْوَقْتِ.",
            "1. La intención.\n2. Golpea la tierra con las manos y se pasa las manos por la cara.\n3. Golpea por segunda vez y se pasa las manos por los brazos hasta los codos.\nLos dos golpes son obligatorios, y el tayammum es válido antes de que entre el tiempo de la oración."),
 'shafii': ("١. النِّيَّةُ عِنْدَ نَقْلِ التُّرَابِ.\n٢. ضَرْبَةٌ لِلْوَجْهِ يَمْسَحُهُ بِهَا.\n٣. ضَرْبَةٌ ثَانِيَةٌ لِلْيَدَيْنِ يَمْسَحُهُمَا إِلَى الْمِرْفَقَيْنِ.\n٤. التَّرْتِيبُ.\nوَدُخُولُ الْوَقْتِ شَرْطٌ، وَيَتَيَمَّمُ لِكُلِّ فَرِيضَةٍ.",
            "1. La intención, al tomar la tierra.\n2. Un golpe para la cara, que se pasa por ella.\n3. Un segundo golpe para las manos, que se pasan hasta los codos.\n4. El orden.\nQue haya entrado el tiempo es condición, y se hace un tayammum para cada oración obligatoria."),
 'hanbali': ("١. النِّيَّةُ.\n٢. التَّسْمِيَةُ (وَاجِبَةٌ مَعَ الذِّكْرِ).\n٣. ضَرْبَةٌ وَاحِدَةٌ يَمْسَحُ بِهَا وَجْهَهُ وَكَفَّيْهِ إِلَى الْكُوعَيْنِ.\nوَالتَّرْتِيبُ وَالْمُوَالَاةُ وَاجِبَانِ فِي الْحَدَثِ الْأَصْغَرِ، وَدُخُولُ الْوَقْتِ شَرْطٌ.",
            "1. La intención.\n2. Decir «Bismillāh» (obligatorio si uno se acuerda).\n3. Un solo golpe, con el que se pasa las manos por la cara y por las manos hasta las muñecas.\nEl orden y la continuidad son obligatorios en la impureza menor, y que haya entrado el tiempo es condición."),
},
'الْمَسْحُ عَلَى الْخُفَّيْنِ': {
 'hanafi': ("يَجُوزُ الْمَسْحُ يَوْمًا وَلَيْلَةً لِلْمُقِيمِ، وَثَلَاثَةَ أَيَّامٍ بِلَيَالِيهَا لِلْمُسَافِرِ، تَبْدَأُ مِنْ أَوَّلِ حَدَثٍ بَعْدَ اللُّبْسِ، بِشَرْطِ أَنْ يَلْبَسَهُمَا عَلَى طَهَارَةٍ كَامِلَةٍ. وَيَجُوزُ عَلَى الْجَوْرَبِ الثَّخِينِ. وَالْفَرْضُ مَسْحُ ظَاهِرِ الْخُفِّ قَدْرَ ثَلَاثِ أَصَابِعَ مِنْ أَصَابِعِ الْيَدِ.",
            "Se permite pasar la mano sobre el calzado un día y una noche al residente, y tres días con sus noches al viajero, contando desde la primera impureza después de ponérselo, con la condición de habérselo puesto en estado de purificación completa. Se permite también sobre calcetines gruesos. Lo obligatorio es pasar sobre la parte de arriba del calzado el ancho de tres dedos de la mano."),
 'shafii': ("يَجُوزُ الْمَسْحُ يَوْمًا وَلَيْلَةً لِلْمُقِيمِ، وَثَلَاثَةَ أَيَّامٍ بِلَيَالِيهَا لِلْمُسَافِرِ، بِشَرْطِ أَنْ يَلْبَسَهُ عَلَى طَهَارَةٍ كَامِلَةٍ، وَأَنْ يَكُونَ سَاتِرًا قَوِيًّا يُمْكِنُ الْمَشْيُ فِيهِ. وَالْوَاجِبُ مَسْحُ شَيْءٍ مِنْ ظَاهِرِ أَعْلَاهُ، وَالسُّنَّةُ مَسْحُ أَعْلَاهُ وَأَسْفَلِهِ خُطُوطًا.",
            "Se permite pasar la mano sobre el calzado un día y una noche al residente, y tres días con sus noches al viajero, si se lo puso en estado de purificación completa y es resistente, cubre y permite caminar. Lo obligatorio es pasar la mano por una parte de la cara superior; la sunna es pasarla por arriba y por abajo, en líneas."),
 'hanbali': ("يَجُوزُ الْمَسْحُ يَوْمًا وَلَيْلَةً لِلْمُقِيمِ، وَثَلَاثَةَ أَيَّامٍ بِلَيَالِيهَا لِلْمُسَافِرِ، بِشَرْطِ اللُّبْسِ عَلَى طَهَارَةٍ كَامِلَةٍ. وَيَجُوزُ عَلَى الْجَوَارِبِ الصَّفِيقَةِ وَعَلَى الْعِمَامَةِ. وَالْوَاجِبُ مَسْحُ أَكْثَرِ أَعْلَى الْخُفِّ، وَلَا يُسَنُّ مَسْحُ أَسْفَلِهِ.",
            "Se permite pasar la mano sobre el calzado un día y una noche al residente, y tres días con sus noches al viajero, si se lo puso en estado de purificación completa. Se permite también sobre calcetines gruesos y sobre el turbante. Lo obligatorio es pasar la mano por la mayor parte de la cara superior; no es sunna pasarla por debajo."),
},
'شُرُوطُ الصَّلَاةِ': {
 'hanafi': ("• شُرُوطُ الصِّحَّةِ: الطَّهَارَةُ مِنَ الْحَدَثِ، وَالطَّهَارَةُ مِنَ النَّجَاسَةِ فِي الْبَدَنِ وَالثَّوْبِ وَالْمَكَانِ، وَسَتْرُ الْعَوْرَةِ، وَاسْتِقْبَالُ الْقِبْلَةِ، وَدُخُولُ الْوَقْتِ، وَالنِّيَّةُ، وَتَكْبِيرَةُ الْإِحْرَامِ.\n• عَوْرَةُ الرَّجُلِ: مِنَ السُّرَّةِ إِلَى الرُّكْبَةِ، وَالرُّكْبَةُ مِنَ الْعَوْرَةِ.\n• عَوْرَةُ الْمَرْأَةِ: جَمِيعُ بَدَنِهَا إِلَّا الْوَجْهَ وَالْكَفَّيْنِ وَالْقَدَمَيْنِ.",
            "• Condiciones de validez: estar purificado; que el cuerpo, la ropa y el lugar estén limpios de impureza; cubrir la ʿawra; orientarse a la qibla; que haya entrado el tiempo; la intención; y el takbīr de entrada.\n• ʿAwra del hombre: del ombligo a las rodillas, rodillas incluidas.\n• ʿAwra de la mujer: todo el cuerpo salvo la cara, las manos y los pies."),
 'shafii': ("• شُرُوطُ الصِّحَّةِ: الطَّهَارَةُ مِنَ الْحَدَثِ، وَالطَّهَارَةُ مِنَ النَّجَاسَةِ فِي الْبَدَنِ وَالثَّوْبِ وَالْمَكَانِ، وَسَتْرُ الْعَوْرَةِ، وَاسْتِقْبَالُ الْقِبْلَةِ، وَمَعْرِفَةُ دُخُولِ الْوَقْتِ.\n• عَوْرَةُ الرَّجُلِ: مَا بَيْنَ السُّرَّةِ وَالرُّكْبَةِ.\n• عَوْرَةُ الْمَرْأَةِ: جَمِيعُ بَدَنِهَا إِلَّا الْوَجْهَ وَالْكَفَّيْنِ.",
            "• Condiciones de validez: estar purificado; que el cuerpo, la ropa y el lugar estén limpios de impureza; cubrir la ʿawra; orientarse a la qibla; y saber que ha entrado el tiempo.\n• ʿAwra del hombre: lo que hay entre el ombligo y las rodillas.\n• ʿAwra de la mujer: todo el cuerpo salvo la cara y las manos."),
 'hanbali': ("• شُرُوطُ الصِّحَّةِ: الْإِسْلَامُ، وَالْعَقْلُ، وَالتَّمْيِيزُ، وَالطَّهَارَةُ مِنَ الْحَدَثِ، وَدُخُولُ الْوَقْتِ، وَسَتْرُ الْعَوْرَةِ، وَاجْتِنَابُ النَّجَاسَةِ، وَاسْتِقْبَالُ الْقِبْلَةِ، وَالنِّيَّةُ.\n• عَوْرَةُ الرَّجُلِ: مَا بَيْنَ السُّرَّةِ وَالرُّكْبَةِ.\n• عَوْرَةُ الْمَرْأَةِ فِي الصَّلَاةِ: جَمِيعُ بَدَنِهَا إِلَّا وَجْهَهَا.",
            "• Condiciones de validez: ser musulmán, estar en uso de razón, tener discernimiento, estar purificado, que haya entrado el tiempo, cubrir la ʿawra, evitar la impureza, orientarse a la qibla y la intención.\n• ʿAwra del hombre: lo que hay entre el ombligo y las rodillas.\n• ʿAwra de la mujer en la oración: todo el cuerpo salvo la cara."),
},
'فَرَائِضُ الصَّلَاةِ': {
 'hanafi': ("الْفَرَائِضُ: التَّحْرِيمَةُ (وَهِيَ شَرْطٌ)، الْقِيَامُ، الْقِرَاءَةُ وَلَوْ آيَةً، الرُّكُوعُ، السُّجُودُ، الْقُعُودُ الْأَخِيرُ قَدْرَ التَّشَهُّدِ، وَالْخُرُوجُ مِنَ الصَّلَاةِ بِفِعْلِ الْمُصَلِّي.\nوَمِنَ الْوَاجِبَاتِ: قِرَاءَةُ الْفَاتِحَةِ، وَضَمُّ سُورَةٍ، وَالطُّمَأْنِينَةُ، وَالتَّشَهُّدَانِ، وَلَفْظُ السَّلَامِ، وَالْقُنُوتُ فِي الْوِتْرِ.\nوَالْمَأْمُومُ لَا يَقْرَأُ خَلْفَ الْإِمَامِ.",
            "Obligatorio (farḍ): el takbīr de entrada (que es condición), estar de pie, recitar aunque sea una aleya, la inclinación, la postración, la última sentada el tiempo del tashahhud y salir de la oración por un acto propio.\nWāŷib: recitar Al-Fātiḥa, añadir una sura, la calma en cada postura, los dos tashahhud, la palabra «salām» y el qunūt del witr.\nQuien reza detrás del imam no recita."),
 'shafii': ("الْأَرْكَانُ: النِّيَّةُ، تَكْبِيرَةُ الْإِحْرَامِ، الْقِيَامُ، قِرَاءَةُ الْفَاتِحَةِ (عَلَى كُلِّ مُصَلٍّ حَتَّى الْمَأْمُومِ)، الرُّكُوعُ، الِاعْتِدَالُ، السُّجُودُ مَرَّتَيْنِ، الْجُلُوسُ بَيْنَ السَّجْدَتَيْنِ، الطُّمَأْنِينَةُ فِي ذَلِكَ كُلِّهِ، التَّشَهُّدُ الْأَخِيرُ، الْقُعُودُ لَهُ، الصَّلَاةُ عَلَى النَّبِيِّ ﷺ فِيهِ، التَّسْلِيمَةُ الْأُولَى، وَالتَّرْتِيبُ.",
            "Pilares: la intención, el takbīr de entrada, estar de pie, recitar Al-Fātiḥa (todo el que reza, también detrás del imam), la inclinación, quedarse recto al incorporarse, las dos postraciones, sentarse entre ellas, la calma en todo ello, el último tashahhud, estar sentado para él, las bendiciones por el Profeta ﷺ en él, el primer saludo y el orden."),
 'hanbali': ("الْأَرْكَانُ أَرْبَعَةَ عَشَرَ: الْقِيَامُ، تَكْبِيرَةُ الْإِحْرَامِ، قِرَاءَةُ الْفَاتِحَةِ (وَيَتَحَمَّلُهَا الْإِمَامُ عَنِ الْمَأْمُومِ)، الرُّكُوعُ، الرَّفْعُ مِنْهُ، الِاعْتِدَالُ، السُّجُودُ عَلَى الْأَعْضَاءِ السَّبْعَةِ، الرَّفْعُ مِنْهُ، الْجُلُوسُ بَيْنَ السَّجْدَتَيْنِ، الطُّمَأْنِينَةُ، التَّشَهُّدُ الْأَخِيرُ، الْجُلُوسُ لَهُ، الصَّلَاةُ عَلَى النَّبِيِّ ﷺ فِيهِ، التَّسْلِيمَتَانِ، وَالتَّرْتِيبُ.",
            "Catorce pilares: estar de pie, el takbīr de entrada, recitar Al-Fātiḥa (el imam la carga por quien reza detrás), la inclinación, incorporarse, quedarse recto, la postración sobre los siete miembros, incorporarse de ella, sentarse entre las dos postraciones, la calma, el último tashahhud, estar sentado para él, las bendiciones por el Profeta ﷺ en él, los dos saludos y el orden."),
},
'١. النِّيَّةُ': {
 'hanafi': ("النِّيَّةُ شَرْطٌ مَحَلُّهَا الْقَلْبُ: أَنْ يَعْلَمَ بِقَلْبِهِ أَيَّ صَلَاةٍ يُصَلِّي. وَاسْتَحْسَنَ بَعْضُ الْحَنَفِيَّةِ التَّلَفُّظَ بِهَا لِجَمْعِ الْقَلْبِ.",
            "La intención es condición y está en el corazón: saber en el corazón qué oración se reza. Algunos hanafíes aprobaron pronunciarla para concentrarse."),
 'shafii': ("النِّيَّةُ رُكْنٌ بِالْقَلْبِ، تَكُونُ مُقَارِنَةً لِتَكْبِيرَةِ الْإِحْرَامِ، وَيُعَيِّنُ فِيهَا الصَّلَاةَ وَأَنَّهَا فَرْضٌ. وَيُسْتَحَبُّ التَّلَفُّظُ بِهَا قَبْلَ التَّكْبِيرِ لِيُسَاعِدَ اللِّسَانُ الْقَلْبَ.",
            "La intención es un pilar que está en el corazón; debe acompañar al takbīr de entrada e indicar qué oración es y que es obligatoria. Es recomendable pronunciarla antes del takbīr para que la lengua ayude al corazón."),
 'hanbali': ("النِّيَّةُ شَرْطٌ مَحَلُّهَا الْقَلْبُ، يُعَيِّنُ فِيهَا الصَّلَاةَ. وَاسْتَحَبَّ بَعْضُ الْمُتَأَخِّرِينَ التَّلَفُّظَ بِهَا سِرًّا، وَالْمُحَقِّقُونَ عَلَى أَنَّهُ لَمْ يَرِدْ عَنِ النَّبِيِّ ﷺ.",
            "La intención es condición y está en el corazón, indicando qué oración es. Algunos hanbalíes posteriores recomendaron pronunciarla en voz baja; los sabios que verificaron la cuestión señalan que no está transmitido del Profeta ﷺ."),
},
'٢. تَكْبِيرَةُ الْإِحْرَامِ: اللَّهُ أَكْبَرُ': {
 'hanafi': ("يَقُولُ: «اللَّهُ أَكْبَرُ»، وَيَرْفَعُ الرَّجُلُ يَدَيْهِ حَتَّى يُحَاذِيَ بِإِبْهَامَيْهِ شَحْمَتَيْ أُذُنَيْهِ، وَالْمَرْأَةُ إِلَى مَنْكِبَيْهَا. وَلَا يَرْفَعُ يَدَيْهِ إِلَّا فِي تَكْبِيرَةِ الْإِحْرَامِ.",
            "Dice «Allāhu akbar». El hombre levanta las manos hasta que los pulgares quedan a la altura del lóbulo de las orejas; la mujer, hasta los hombros. Solo se levantan las manos en el takbīr de entrada."),
 'shafii': ("يَقُولُ: «اللَّهُ أَكْبَرُ» رَافِعًا يَدَيْهِ حَذْوَ مَنْكِبَيْهِ. وَيُسَنُّ رَفْعُهُمَا أَيْضًا عِنْدَ الرُّكُوعِ، وَعِنْدَ الرَّفْعِ مِنْهُ، وَعِنْدَ الْقِيَامِ مِنَ التَّشَهُّدِ الْأَوَّلِ.",
            "Dice «Allāhu akbar» levantando las manos a la altura de los hombros. También es sunna levantarlas al inclinarse, al incorporarse de la inclinación y al levantarse del primer tashahhud."),
 'hanbali': ("يَقُولُ: «اللَّهُ أَكْبَرُ» رَافِعًا يَدَيْهِ حَذْوَ مَنْكِبَيْهِ أَوْ إِلَى فُرُوعِ أُذُنَيْهِ. وَيُسَنُّ رَفْعُهُمَا أَيْضًا عِنْدَ الرُّكُوعِ وَعِنْدَ الرَّفْعِ مِنْهُ.",
            "Dice «Allāhu akbar» levantando las manos a la altura de los hombros o de la parte alta de las orejas. También es sunna levantarlas al inclinarse y al incorporarse de la inclinación."),
},
'٣. الْقِيَامُ وَوَضْعُ الْيَدَيْنِ': {
 'hanafi': ("يَضَعُ الرَّجُلُ يَدَهُ الْيُمْنَى عَلَى الْيُسْرَى تَحْتَ السُّرَّةِ، وَالْمَرْأَةُ عَلَى صَدْرِهَا، وَيَنْظُرُ إِلَى مَوْضِعِ سُجُودِهِ.",
            "El hombre pone la mano derecha sobre la izquierda bajo el ombligo, y la mujer sobre el pecho. Mira al lugar donde se va a postrar."),
 'shafii': ("يَضَعُ يَدَهُ الْيُمْنَى عَلَى الْيُسْرَى تَحْتَ الصَّدْرِ فَوْقَ السُّرَّةِ، وَيَنْظُرُ إِلَى مَوْضِعِ سُجُودِهِ.",
            "Pone la mano derecha sobre la izquierda bajo el pecho, por encima del ombligo, y mira al lugar donde se va a postrar."),
 'hanbali': ("يَضَعُ يَدَهُ الْيُمْنَى عَلَى كُوعِ الْيُسْرَى تَحْتَ سُرَّتِهِ، وَيَنْظُرُ إِلَى مَوْضِعِ سُجُودِهِ.",
            "Pone la mano derecha sobre la muñeca izquierda bajo el ombligo, y mira al lugar donde se va a postrar."),
},
'٤. الْقِرَاءَةُ: الْفَاتِحَةُ ثُمَّ سُورَةٌ': {
 'hanafi': ("يَسْتَفْتِحُ: «سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، وَتَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلَهَ غَيْرُكَ»، ثُمَّ يَتَعَوَّذُ، وَيُبَسْمِلُ سِرًّا، وَيَقْرَأُ الْفَاتِحَةَ وَسُورَةً فِي الْأُولَيَيْنِ، وَالْفَاتِحَةَ فِي الْأُخْرَيَيْنِ. يَقُولُ الْإِمَامُ وَالْمَأْمُومُ: «آمِينَ» سِرًّا. وَالْمَأْمُومُ لَا يَقْرَأُ خَلْفَ الْإِمَامِ.",
            "Hace la súplica de apertura: «Subḥānaka-llāhumma wa bi-ḥamdik, wa tabāraka-smuk, wa taʿālā ŷadduk, wa lā ilāha ghayruk»; luego el taʿawwudh y la basmala en voz baja, y recita Al-Fātiḥa y una sura en las dos primeras rakʿas, y Al-Fātiḥa en las dos últimas. El imam y quien le sigue dicen «Āmīn» en voz baja. Quien reza detrás del imam no recita."),
 'shafii': ("يَسْتَفْتِحُ: «وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَاوَاتِ وَالْأَرْضَ…»، ثُمَّ يَتَعَوَّذُ سِرًّا، ثُمَّ يَقْرَأُ الْفَاتِحَةَ، وَالْبَسْمَلَةُ آيَةٌ مِنْهَا يَجْهَرُ بِهَا فِي الْجَهْرِيَّةِ، ثُمَّ سُورَةً فِي الْأُولَيَيْنِ. يَجْهَرُ الْإِمَامُ وَالْمَأْمُومُ بِـ«آمِينَ» فِي الْجَهْرِيَّةِ. وَالْمَأْمُومُ يَقْرَأُ الْفَاتِحَةَ وُجُوبًا.",
            "Hace la súplica de apertura: «Waŷŷahtu waŷhiya lil-ladhī faṭaras-samāwāti wal-arḍ…»; luego el taʿawwudh en voz baja, y recita Al-Fātiḥa, de la que la basmala es una aleya y se dice en voz alta en las oraciones en voz alta; después una sura en las dos primeras rakʿas. El imam y quien le sigue dicen «Āmīn» en voz alta en las oraciones en voz alta. Quien reza detrás del imam debe recitar Al-Fātiḥa."),
 'hanbali': ("يَسْتَفْتِحُ: «سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ…»، ثُمَّ يَتَعَوَّذُ، وَيُبَسْمِلُ سِرًّا، ثُمَّ يَقْرَأُ الْفَاتِحَةَ وَسُورَةً فِي الْأُولَيَيْنِ. يَجْهَرُ الْإِمَامُ وَالْمَأْمُومُ بِـ«آمِينَ» فِي الْجَهْرِيَّةِ. وَيُسْتَحَبُّ لِلْمَأْمُومِ أَنْ يَقْرَأَ فِي سَكَتَاتِ الْإِمَامِ وَفِي السِّرِّيَّةِ.",
            "Hace la súplica de apertura: «Subḥānaka-llāhumma wa bi-ḥamdik…»; luego el taʿawwudh y la basmala en voz baja, y recita Al-Fātiḥa y una sura en las dos primeras rakʿas. El imam y quien le sigue dicen «Āmīn» en voz alta en las oraciones en voz alta. A quien reza detrás del imam se le recomienda recitar en las pausas del imam y en las oraciones en voz baja."),
},
'٥. الرُّكُوعُ: سُبْحَانَ رَبِّيَ الْعَظِيمِ': {
 'hanafi': ("يُكَبِّرُ وَيَرْكَعُ بِلَا رَفْعٍ لِلْيَدَيْنِ، وَيَضَعُ يَدَيْهِ عَلَى رُكْبَتَيْهِ مُفَرِّجًا أَصَابِعَهُ، وَيَقُولُ: «سُبْحَانَ رَبِّيَ الْعَظِيمِ» ثَلَاثًا، وَهُوَ سُنَّةٌ. وَالطُّمَأْنِينَةُ وَاجِبَةٌ.",
            "Dice «Allāhu akbar» y se inclina sin levantar las manos; pone las manos sobre las rodillas con los dedos separados y dice «Subḥāna Rabbiyal-ʿAẓīm» tres veces, lo cual es sunna. La calma es wāŷib."),
 'shafii': ("يَرْفَعُ يَدَيْهِ مُكَبِّرًا وَيَرْكَعُ، وَيَضَعُ يَدَيْهِ عَلَى رُكْبَتَيْهِ، وَيَقُولُ: «سُبْحَانَ رَبِّيَ الْعَظِيمِ» ثَلَاثًا، وَهُوَ سُنَّةٌ. وَالطُّمَأْنِينَةُ رُكْنٌ.",
            "Levanta las manos diciendo «Allāhu akbar» y se inclina; pone las manos sobre las rodillas y dice «Subḥāna Rabbiyal-ʿAẓīm» tres veces, lo cual es sunna. La calma es pilar."),
 'hanbali': ("يَرْفَعُ يَدَيْهِ مُكَبِّرًا وَيَرْكَعُ، وَيَقُولُ: «سُبْحَانَ رَبِّيَ الْعَظِيمِ»، وَالْمَرَّةُ الْوَاحِدَةُ وَاجِبَةٌ، وَأَدْنَى الْكَمَالِ ثَلَاثٌ. وَالطُّمَأْنِينَةُ رُكْنٌ.",
            "Levanta las manos diciendo «Allāhu akbar» y se inclina, y dice «Subḥāna Rabbiyal-ʿAẓīm»; decirlo una vez es wāŷib y lo mínimo recomendable son tres. La calma es pilar."),
},
'٧. السُّجُودُ: سُبْحَانَ رَبِّيَ الْأَعْلَى': {
 'hanafi': ("يُكَبِّرُ وَيَنْزِلُ بِرُكْبَتَيْهِ ثُمَّ يَدَيْهِ، وَيَسْجُدُ عَلَى جَبْهَتِهِ وَأَنْفِهِ، وَيَقُولُ: «سُبْحَانَ رَبِّيَ الْأَعْلَى» ثَلَاثًا، وَهُوَ سُنَّةٌ.",
            "Dice «Allāhu akbar» y baja apoyando primero las rodillas y luego las manos; se postra sobre la frente y la nariz, y dice «Subḥāna Rabbiyal-Aʿlā» tres veces, lo cual es sunna."),
 'shafii': ("يُكَبِّرُ وَيَنْزِلُ بِرُكْبَتَيْهِ ثُمَّ يَدَيْهِ، وَيَسْجُدُ عَلَى الْأَعْضَاءِ السَّبْعَةِ وُجُوبًا وَالْجَبْهَةُ مَكْشُوفَةٌ، وَيَقُولُ: «سُبْحَانَ رَبِّيَ الْأَعْلَى» ثَلَاثًا، وَهُوَ سُنَّةٌ.",
            "Dice «Allāhu akbar» y baja apoyando primero las rodillas y luego las manos; postrarse sobre los siete miembros es obligatorio, con la frente descubierta, y dice «Subḥāna Rabbiyal-Aʿlā» tres veces, lo cual es sunna."),
 'hanbali': ("يُكَبِّرُ وَيَنْزِلُ بِرُكْبَتَيْهِ ثُمَّ يَدَيْهِ، وَالسُّجُودُ عَلَى الْأَعْضَاءِ السَّبْعَةِ مَعَ الْأَنْفِ رُكْنٌ، وَيَقُولُ: «سُبْحَانَ رَبِّيَ الْأَعْلَى»، وَالْمَرَّةُ الْوَاحِدَةُ وَاجِبَةٌ.",
            "Dice «Allāhu akbar» y baja apoyando primero las rodillas y luego las manos; postrarse sobre los siete miembros y la nariz es pilar, y dice «Subḥāna Rabbiyal-Aʿlā»: decirlo una vez es wāŷib."),
},
'٩. التَّشَهُّدُ': {
 'hanafi': ("تَشَهُّدُ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ:\n«التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ».\nالْجِلْسَةُ: الِافْتِرَاشُ فِي الْجُلُوسَيْنِ لِلرَّجُلِ: يَجْلِسُ عَلَى رِجْلِهِ الْيُسْرَى وَيَنْصِبُ الْيُمْنَى. يَرْفَعُ السَّبَّابَةَ عِنْدَ «لَا إِلَهَ» وَيَضَعُهَا عِنْدَ «إِلَّا اللَّهُ». وَالتَّشَهُّدَانِ وَاجِبَانِ.",
            "Tashahhud de Ibn Masʿūd:\n«At-taḥiyyātu lillāhi waṣ-ṣalawātu waṭ-ṭayyibāt. As-salāmu ʿalayka ayyuhan-nabiyyu wa raḥmatullāhi wa barakātuh. As-salāmu ʿalaynā wa ʿalā ʿibādillāhiṣ-ṣāliḥīn. Ashhadu an lā ilāha illallāh, wa ashhadu anna Muḥammadan ʿabduhū wa rasūluh».\nForma de sentarse: el hombre se sienta sobre el pie izquierdo con el derecho levantado (iftirāsh) en las dos sentadas. Levanta el índice en «lā ilāha» y lo baja en «illallāh». Los dos tashahhud son wāŷib."),
 'shafii': ("تَشَهُّدُ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا:\n«التَّحِيَّاتُ الْمُبَارَكَاتُ الصَّلَوَاتُ الطَّيِّبَاتُ لِلَّهِ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ».\nالْجِلْسَةُ: الِافْتِرَاشُ فِي الْأَوَّلِ، وَالتَّوَرُّكُ فِي الْأَخِيرِ. يَقْبِضُ أَصَابِعَ الْيُمْنَى إِلَّا الْمُسَبِّحَةَ وَيَرْفَعُهَا عِنْدَ «إِلَّا اللَّهُ». التَّشَهُّدُ الْأَوَّلُ سُنَّةٌ (مِنَ الْأَبْعَاضِ)، وَالْأَخِيرُ رُكْنٌ.",
            "Tashahhud de Ibn ʿAbbās:\n«At-taḥiyyātul-mubārakātuṣ-ṣalawātuṭ-ṭayyibātu lillāh. As-salāmu ʿalayka ayyuhan-nabiyyu wa raḥmatullāhi wa barakātuh. As-salāmu ʿalaynā wa ʿalā ʿibādillāhiṣ-ṣāliḥīn. Ashhadu an lā ilāha illallāh, wa ashhadu anna Muḥammadan rasūlullāh».\nForma de sentarse: iftirāsh en la primera sentada y tawarruk en la última. Cierra los dedos de la mano derecha salvo el índice, que levanta en «illallāh». El primer tashahhud es sunna (de las abʿāḍ) y el último es pilar."),
 'hanbali': ("تَشَهُّدُ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ:\n«التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ».\nالْجِلْسَةُ: الِافْتِرَاشُ، وَالتَّوَرُّكُ فِي التَّشَهُّدِ الْأَخِيرِ مِنْ صَلَاةٍ فِيهَا تَشَهُّدَانِ. يُشِيرُ بِالسَّبَّابَةِ عِنْدَ ذِكْرِ اللَّهِ. التَّشَهُّدُ الْأَوَّلُ وَاجِبٌ، وَالْأَخِيرُ رُكْنٌ.",
            "Tashahhud de Ibn Masʿūd:\n«At-taḥiyyātu lillāhi waṣ-ṣalawātu waṭ-ṭayyibāt. As-salāmu ʿalayka ayyuhan-nabiyyu wa raḥmatullāhi wa barakātuh. As-salāmu ʿalaynā wa ʿalā ʿibādillāhiṣ-ṣāliḥīn. Ashhadu an lā ilāha illallāh, wa ashhadu anna Muḥammadan ʿabduhū wa rasūluh».\nForma de sentarse: iftirāsh, y tawarruk en el último tashahhud de las oraciones con dos tashahhud. Señala con el índice cada vez que menciona a Allah. El primer tashahhud es wāŷib y el último es pilar."),
},
'١٠. الصَّلَاةُ عَلَى النَّبِيِّ ﷺ وَالدُّعَاءُ': {
 'hanafi': ("بَعْدَ التَّشَهُّدِ الْأَخِيرِ يُصَلِّي عَلَى النَّبِيِّ ﷺ بِالصِّيغَةِ الْإِبْرَاهِيمِيَّةِ، وَهِيَ سُنَّةٌ، ثُمَّ يَدْعُو بِمَا يُشْبِهُ أَلْفَاظَ الْقُرْآنِ وَالسُّنَّةِ.",
            "Después del último tashahhud pide bendiciones por el Profeta ﷺ con la fórmula de Ibrāhīm, lo cual es sunna; después suplica con palabras parecidas a las del Corán y la Sunna."),
 'shafii': ("الصَّلَاةُ عَلَى النَّبِيِّ ﷺ فِي التَّشَهُّدِ الْأَخِيرِ رُكْنٌ، وَأَقَلُّهَا: «اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ»، وَأَكْمَلُهَا الصِّيغَةُ الْإِبْرَاهِيمِيَّةُ. وَالصَّلَاةُ عَلَى الْآلِ سُنَّةٌ. ثُمَّ يَدْعُو، وَمِنْهُ الِاسْتِعَاذَةُ مِنَ الْأَرْبَعِ.",
            "Las bendiciones por el Profeta ﷺ en el último tashahhud son un pilar; lo mínimo es «Allāhumma ṣalli ʿalā Muḥammad» y lo completo es la fórmula de Ibrāhīm. Incluir a su familia es sunna. Después suplica, por ejemplo refugiándose de las cuatro cosas (el Infierno, la tumba, las pruebas de la vida y la muerte, y el Daŷŷāl)."),
 'hanbali': ("الصَّلَاةُ عَلَى النَّبِيِّ ﷺ فِي التَّشَهُّدِ الْأَخِيرِ رُكْنٌ، بِالصِّيغَةِ الْإِبْرَاهِيمِيَّةِ، ثُمَّ يُسْتَحَبُّ الدُّعَاءُ، وَمِنْهُ الِاسْتِعَاذَةُ مِنْ عَذَابِ جَهَنَّمَ وَعَذَابِ الْقَبْرِ وَفِتْنَةِ الْمَحْيَا وَالْمَمَاتِ وَفِتْنَةِ الْمَسِيحِ الدَّجَّالِ.",
            "Las bendiciones por el Profeta ﷺ en el último tashahhud son un pilar, con la fórmula de Ibrāhīm. Después se recomienda suplicar, por ejemplo refugiándose del castigo del Infierno, del castigo de la tumba, de las pruebas de la vida y de la muerte y de la prueba del Daŷŷāl."),
},
'١١. السَّلَامُ: السَّلَامُ عَلَيْكُمْ': {
 'hanafi': ("يُسَلِّمُ يَمِينًا ثُمَّ يَسَارًا قَائِلًا: «السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ». وَلَفْظُ السَّلَامِ وَاجِبٌ، وَالْفَرْضُ الْخُرُوجُ مِنَ الصَّلَاةِ بِفِعْلِ الْمُصَلِّي.",
            "Saluda a la derecha y luego a la izquierda diciendo «As-salāmu ʿalaykum wa raḥmatullāh». La palabra «salām» es wāŷib; lo farḍ es salir de la oración por un acto propio."),
 'shafii': ("يُسَلِّمُ قَائِلًا: «السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ» يَمِينًا ثُمَّ يَسَارًا. التَّسْلِيمَةُ الْأُولَى رُكْنٌ، وَالثَّانِيَةُ سُنَّةٌ.",
            "Saluda diciendo «As-salāmu ʿalaykum wa raḥmatullāh» a la derecha y luego a la izquierda. El primer saludo es pilar y el segundo, sunna."),
 'hanbali': ("يُسَلِّمُ قَائِلًا: «السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ» يَمِينًا ثُمَّ يَسَارًا، وَالتَّسْلِيمَتَانِ رُكْنَانِ فِي الْفَرِيضَةِ.",
            "Saluda diciendo «As-salāmu ʿalaykum wa raḥmatullāh» a la derecha y luego a la izquierda. En la oración obligatoria los dos saludos son pilares."),
},
'الْقُنُوتُ فِي صَلَاةِ الصُّبْحِ': {
 'hanafi': ("لَا قُنُوتَ فِي صَلَاةِ الصُّبْحِ إِلَّا فِي النَّوَازِلِ. وَمَحَلُّهُ صَلَاةُ الْوِتْرِ، فِي الرَّكْعَةِ الثَّالِثَةِ قَبْلَ الرُّكُوعِ، طُولَ السَّنَةِ، وَهُوَ وَاجِبٌ، بِلَفْظِ: «اللَّهُمَّ إِنَّا نَسْتَعِينُكَ وَنَسْتَغْفِرُكَ…».",
            "No hay qunūt en el Fajr salvo en calamidades. Su lugar es el witr, en la tercera rakʿa antes de la inclinación, todo el año, y es wāŷib, con la fórmula «Allāhumma innā nastaʿīnuka wa nastaghfiruk…»."),
 'shafii': ("الْقُنُوتُ سُنَّةٌ فِي الصُّبْحِ بَعْدَ الرَّفْعِ مِنْ رُكُوعِ الثَّانِيَةِ، يَرْفَعُ فِيهِ يَدَيْهِ وَيَجْهَرُ بِهِ الْإِمَامُ، بِلَفْظِ: «اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ…». وَيُقْنَتُ فِي وِتْرِ النِّصْفِ الثَّانِي مِنْ رَمَضَانَ.",
            "El qunūt es sunna en el Fajr después de incorporarse de la inclinación de la segunda rakʿa, levantando las manos; el imam lo dice en voz alta, con la fórmula «Allāhumma-hdinī fīman hadayt, wa ʿāfinī fīman ʿāfayt…». También se hace en el witr de la segunda mitad de Ramadán."),
 'hanbali': ("لَا قُنُوتَ فِي صَلَاةِ الصُّبْحِ إِلَّا فِي النَّوَازِلِ. وَمَحَلُّهُ صَلَاةُ الْوِتْرِ بَعْدَ الرُّكُوعِ، طُولَ السَّنَةِ، بِلَفْظِ: «اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ…».",
            "No hay qunūt en el Fajr salvo en calamidades. Su lugar es el witr, después de la inclinación, todo el año, con la fórmula «Allāhumma-hdinī fīman hadayt…»."),
},
'الصَّلَوَاتُ الْخَمْسُ': {
 'hanafi': ("عَدَدُ الرَّكَعَاتِ وَمَوَاضِعُ الْجَهْرِ كَمَا سَبَقَ. وَالْقَصْرُ فِي السَّفَرِ وَاجِبٌ (عَزِيمَةٌ): يُصَلِّي الرُّبَاعِيَّةَ رَكْعَتَيْنِ، فَإِنْ أَتَمَّ أَسَاءَ.",
            "El número de rakʿas y las partes en voz alta son iguales. En el viaje, acortar es obligatorio: las oraciones de cuatro se rezan de dos, y quien reza las cuatro obra mal."),
 'shafii': ("عَدَدُ الرَّكَعَاتِ وَمَوَاضِعُ الْجَهْرِ كَمَا سَبَقَ. وَالْقَصْرُ فِي السَّفَرِ رُخْصَةٌ يَجُوزُ تَرْكُهَا، وَهُوَ أَفْضَلُ إِذَا بَلَغَ السَّفَرُ ثَلَاثَ مَرَاحِلَ.",
            "El número de rakʿas y las partes en voz alta son iguales. En el viaje, acortar es una facilidad que se puede no usar; es preferible si el viaje alcanza tres etapas."),
 'hanbali': ("عَدَدُ الرَّكَعَاتِ وَمَوَاضِعُ الْجَهْرِ كَمَا سَبَقَ. وَالْقَصْرُ فِي السَّفَرِ رُخْصَةٌ، وَهُوَ أَفْضَلُ مِنَ الْإِتْمَامِ.",
            "El número de rakʿas y las partes en voz alta son iguales. En el viaje, acortar es una facilidad, y es preferible a rezar completo."),
},
'الرَّغِيبَةُ وَالْوِتْرُ': {
 'hanafi': ("• سُنَّةُ الْفَجْرِ: رَكْعَتَانِ قَبْلَ الصُّبْحِ، يَقْرَأُ فِيهِمَا بَعْدَ الْفَاتِحَةِ «الْكَافِرُونَ» وَ«الْإِخْلَاصُ»، وَهِيَ آكَدُ السُّنَنِ.\n• الْوِتْرُ: وَاجِبٌ، ثَلَاثُ رَكَعَاتٍ بِتَشَهُّدَيْنِ وَسَلَامٍ وَاحِدٍ كَالْمَغْرِبِ، مَعَ الْقُنُوتِ قَبْلَ الرُّكُوعِ فِي الثَّالِثَةِ.",
            "• Sunna del Fajr: dos rakʿas antes del Fajr; tras Al-Fātiḥa se recitan Al-Kāfirūn y Al-Ijlāṣ. Es la sunna más confirmada.\n• Witr: es wāŷib; tres rakʿas con dos tashahhud y un solo salām, como el Maghrib, con qunūt antes de la inclinación de la tercera."),
 'shafii': ("• سُنَّةُ الْفَجْرِ: رَكْعَتَانِ يَقْرَأُ فِيهِمَا «الْكَافِرُونَ» وَ«الْإِخْلَاصُ».\n• الْوِتْرُ: سُنَّةٌ مُؤَكَّدَةٌ، أَقَلُّهُ رَكْعَةٌ وَأَكْثَرُهُ إِحْدَى عَشْرَةَ، وَالْأَفْضَلُ الْفَصْلُ بَيْنَ الشَّفْعِ وَالْوِتْرِ بِسَلَامٍ.",
            "• Sunna del Fajr: dos rakʿas, recitando Al-Kāfirūn y Al-Ijlāṣ.\n• Witr: sunna confirmada; como mínimo una rakʿa y como máximo once; es mejor separar con un salām el shafʿ del witr."),
 'hanbali': ("• سُنَّةُ الْفَجْرِ: رَكْعَتَانِ يَقْرَأُ فِيهِمَا «الْكَافِرُونَ» وَ«الْإِخْلَاصُ».\n• الْوِتْرُ: سُنَّةٌ مُؤَكَّدَةٌ، أَقَلُّهُ رَكْعَةٌ وَأَكْثَرُهُ إِحْدَى عَشْرَةَ، وَأَدْنَى الْكَمَالِ ثَلَاثٌ بِسَلَامَيْنِ، مَعَ الْقُنُوتِ بَعْدَ الرُّكُوعِ.",
            "• Sunna del Fajr: dos rakʿas, recitando Al-Kāfirūn y Al-Ijlāṣ.\n• Witr: sunna confirmada; como mínimo una rakʿa y como máximo once; lo mínimo recomendable son tres con dos salām, con qunūt después de la inclinación."),
},
'مَتَى يُسْجَدُ لِلسَّهْوِ؟': {
 'hanafi': ("سُجُودُ السَّهْوِ وَاجِبٌ لِتَرْكِ وَاجِبٍ أَوْ تَأْخِيرِهِ، أَوْ تَأْخِيرِ رُكْنٍ سَهْوًا. وَهُوَ كُلُّهُ بَعْدَ السَّلَامِ، سَوَاءٌ كَانَ عَنْ نَقْصٍ أَوْ زِيَادَةٍ.\nوَمَنْ شَكَّ فِي عَدَدِ الرَّكَعَاتِ عَمِلَ بِغَالِبِ ظَنِّهِ، فَإِنْ لَمْ يَتَرَجَّحْ لَهُ شَيْءٌ بَنَى عَلَى الْأَقَلِّ.",
            "La postración del olvido es wāŷib por omitir o retrasar un wāŷib, o retrasar un pilar por olvido. Siempre se hace después del salām, sea por omisión o por añadido.\nQuien duda del número de rakʿas sigue lo que le parece más probable; si no tiene preferencia, cuenta el número menor."),
 'shafii': ("سُجُودُ السَّهْوِ سُنَّةٌ، يُشْرَعُ لِتَرْكِ بَعْضٍ مِنَ الْأَبْعَاضِ، أَوْ لِفِعْلِ مَا يُبْطِلُ عَمْدُهُ سَهْوًا، أَوْ لِلشَّكِّ فِي عَدَدِ الرَّكَعَاتِ. وَهُوَ كُلُّهُ قَبْلَ السَّلَامِ.\nوَمَنْ شَكَّ بَنَى عَلَى الْيَقِينِ وَهُوَ الْأَقَلُّ.",
            "La postración del olvido es sunna: se hace por omitir una de las abʿāḍ, por hacer por olvido algo que a propósito invalidaría la oración, o por dudar del número de rakʿas. Siempre se hace antes del salām.\nQuien duda cuenta lo seguro, el número menor."),
 'hanbali': ("سُجُودُ السَّهْوِ وَاجِبٌ لِمَا يُبْطِلُ عَمْدُهُ الصَّلَاةَ مِنْ زِيَادَةٍ أَوْ نَقْصٍ أَوْ شَكٍّ، وَيُسَنُّ لِغَيْرِهِ.\nوَهُوَ قَبْلَ السَّلَامِ، إِلَّا إِذَا سَلَّمَ قَبْلَ تَمَامِ صَلَاتِهِ، أَوْ بَنَى الْإِمَامُ عَلَى غَالِبِ ظَنِّهِ، فَيَسْجُدُ بَعْدَ السَّلَامِ.\nوَمَنْ شَكَّ بَنَى عَلَى الْيَقِينِ (لِلْمُنْفَرِدِ)، وَالْإِمَامُ يَعْمَلُ بِغَالِبِ ظَنِّهِ.",
            "La postración del olvido es wāŷib por lo que a propósito invalidaría la oración (añadido, omisión o duda), y sunna en lo demás.\nSe hace antes del salām, salvo si saludó antes de terminar o si el imam siguió lo más probable: entonces se hace después del salām.\nQuien reza solo y duda cuenta lo seguro; el imam sigue lo que le parece más probable."),
},
'صِفَةُ سُجُودِ السَّهْوِ': {
 'hanafi': ("بَعْدَ التَّشَهُّدِ الْأَخِيرِ يُسَلِّمُ تَسْلِيمَةً وَاحِدَةً عَنْ يَمِينِهِ، ثُمَّ يُكَبِّرُ وَيَسْجُدُ سَجْدَتَيْنِ، ثُمَّ يَجْلِسُ فَيَتَشَهَّدُ، وَيُصَلِّي عَلَى النَّبِيِّ ﷺ وَيَدْعُو، ثُمَّ يُسَلِّمُ.",
            "Tras el último tashahhud saluda una vez a la derecha, dice «Allāhu akbar» y hace dos postraciones; después se sienta, repite el tashahhud, pide bendiciones por el Profeta ﷺ, suplica y saluda."),
 'shafii': ("بَعْدَ التَّشَهُّدِ الْأَخِيرِ وَالصَّلَاةِ عَلَى النَّبِيِّ ﷺ وَقَبْلَ السَّلَامِ، يَسْجُدُ سَجْدَتَيْنِ يُكَبِّرُ لَهُمَا، ثُمَّ يُسَلِّمُ مُبَاشَرَةً بِلَا تَشَهُّدٍ.",
            "Tras el último tashahhud y las bendiciones por el Profeta ﷺ, antes del salām, hace dos postraciones diciendo «Allāhu akbar», y luego saluda directamente, sin repetir el tashahhud."),
 'hanbali': ("• إِذَا كَانَ قَبْلَ السَّلَامِ: يَسْجُدُ سَجْدَتَيْنِ بَعْدَ التَّشَهُّدِ الْأَخِيرِ، ثُمَّ يُسَلِّمُ مُبَاشَرَةً بِلَا تَشَهُّدٍ.\n• إِذَا كَانَ بَعْدَ السَّلَامِ: يُسَلِّمُ، ثُمَّ يَسْجُدُ سَجْدَتَيْنِ، ثُمَّ يَتَشَهَّدُ التَّشَهُّدَ الْأَخِيرَ وَيُسَلِّمُ.",
            "• Si es antes del salām: hace dos postraciones tras el último tashahhud y saluda directamente, sin tashahhud.\n• Si es después del salām: saluda, hace dos postraciones, repite el último tashahhud y saluda."),
},
'حَالَاتُ السُّجُودِ الْقَبْلِيِّ (لِلنَّقْصِ)': {
 'hanafi': ("يَسْجُدُ (بَعْدَ السَّلَامِ) إِذَا تَرَكَ وَاجِبًا سَهْوًا، مِثْلَ:\n• قِرَاءَةِ الْفَاتِحَةِ أَوِ السُّورَةِ.\n• التَّشَهُّدِ الْأَوَّلِ أَوِ الْقُعُودِ لَهُ.\n• الْجَهْرِ فِي مَوْضِعِ الْإِسْرَارِ أَوِ الْعَكْسِ.\n• الْقُنُوتِ فِي الْوِتْرِ.\n• تَأْخِيرِ رُكْنٍ عَنْ مَوْضِعِهِ.",
            "Se postra (después del salām) si omite por olvido un wāŷib, por ejemplo:\n• Recitar Al-Fātiḥa o la sura.\n• El primer tashahhud o sentarse para él.\n• Recitar en voz alta donde va en voz baja, o al revés.\n• El qunūt del witr.\n• Retrasar un pilar de su sitio."),
 'shafii': ("يَسْجُدُ قَبْلَ السَّلَامِ لِتَرْكِ الْأَبْعَاضِ:\n• التَّشَهُّدِ الْأَوَّلِ.\n• الْقُعُودِ لَهُ.\n• الصَّلَاةِ عَلَى النَّبِيِّ ﷺ فِيهِ.\n• الْقُنُوتِ فِي الصُّبْحِ.\nوَلَا يَسْجُدُ لِتَرْكِ السُّورَةِ أَوِ التَّكْبِيرَاتِ أَوِ الْجَهْرِ وَالْإِسْرَارِ، لِأَنَّهَا مِنَ الْهَيْئَاتِ.",
            "Se postra antes del salām por omitir las abʿāḍ:\n• El primer tashahhud.\n• Sentarse para él.\n• Las bendiciones por el Profeta ﷺ en él.\n• El qunūt del Fajr.\nNo se postra por omitir la sura, los takbīr o la voz alta o baja, porque son hayʾāt."),
 'hanbali': ("يَسْجُدُ قَبْلَ السَّلَامِ وُجُوبًا لِتَرْكِ وَاجِبٍ سَهْوًا، مِثْلَ:\n• تَكْبِيرَاتِ الِانْتِقَالِ.\n• «سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ» وَ«رَبَّنَا وَلَكَ الْحَمْدُ».\n• «سُبْحَانَ رَبِّيَ الْعَظِيمِ» وَ«سُبْحَانَ رَبِّيَ الْأَعْلَى» مَرَّةً.\n• «رَبِّ اغْفِرْ لِي» بَيْنَ السَّجْدَتَيْنِ.\n• التَّشَهُّدِ الْأَوَّلِ وَالْجُلُوسِ لَهُ.\nوَلَا يَجِبُ السُّجُودُ لِتَرْكِ السُّنَنِ.",
            "Debe postrarse antes del salām por omitir un wāŷib por olvido, por ejemplo:\n• Los takbīr de transición.\n• «Samiʿallāhu liman ḥamidah» y «Rabbanā wa lakal-ḥamd».\n• «Subḥāna Rabbiyal-ʿAẓīm» y «Subḥāna Rabbiyal-Aʿlā», una vez.\n• «Rabbigh-fir lī» entre las dos postraciones.\n• El primer tashahhud y sentarse para él.\nNo es obligatorio postrarse por omitir una sunna."),
},
'حَالَاتُ السُّجُودِ الْبَعْدِيِّ (لِلزِّيَادَةِ)': {
 'hanafi': ("كُلُّ سُجُودِ السَّهْوِ بَعْدَ السَّلَامِ:\n• إِنْ قَامَ إِلَى خَامِسَةٍ قَبْلَ أَنْ يَقْعُدَ قَدْرَ التَّشَهُّدِ: يَعُودُ مَا لَمْ يَسْجُدْ، فَإِنْ سَجَدَ صَارَتْ نَافِلَةً وَبَطَلَ فَرْضُهُ.\n• وَإِنْ قَعَدَ قَدْرَ التَّشَهُّدِ ثُمَّ قَامَ إِلَى خَامِسَةٍ: يَعُودُ وَيُسَلِّمُ وَيَسْجُدُ، فَإِنْ سَجَدَ لَهَا ضَمَّ إِلَيْهَا سَادِسَةً وَسَجَدَ لِلسَّهْوِ.\n• الْكَلَامُ فِي الصَّلَاةِ يُبْطِلُهَا وَلَوْ سَهْوًا.\n• فِي الشَّكِّ: يَعْمَلُ بِغَالِبِ ظَنِّهِ، وَإِلَّا بَنَى عَلَى الْأَقَلِّ.",
            "Toda postración del olvido es después del salām:\n• Si se levanta a una quinta rakʿa antes de haberse sentado el tiempo del tashahhud: vuelve mientras no se haya postrado; si se postró, esa oración se vuelve voluntaria y la obligatoria no es válida.\n• Si ya se había sentado el tiempo del tashahhud y se levantó a una quinta: vuelve, saluda y se postra; si llegó a postrarse en ella, añade una sexta y hace la postración del olvido.\n• Hablar en la oración la invalida, aunque sea por olvido.\n• En la duda: sigue lo más probable; si no lo tiene claro, cuenta el número menor."),
 'shafii': ("يَسْجُدُ قَبْلَ السَّلَامِ لِكُلِّ زِيَادَةٍ سَهْوًا:\n• إِنْ زَادَ رَكْعَةً: يَجْلِسُ مَتَى تَذَكَّرَ، وَيَتَشَهَّدُ وَيَسْجُدُ ثُمَّ يُسَلِّمُ.\n• إِنْ سَلَّمَ قَبْلَ تَمَامِهَا وَتَذَكَّرَ قَرِيبًا: يُكْمِلُ وَيَسْجُدُ قَبْلَ السَّلَامِ.\n• الْكَلَامُ الْيَسِيرُ سَهْوًا لَا يُبْطِلُ الصَّلَاةَ وَيَسْجُدُ لَهُ.\n• فِي الشَّكِّ: يَبْنِي عَلَى الْيَقِينِ وَيَسْجُدُ قَبْلَ السَّلَامِ.",
            "Se postra antes del salām por todo añadido por olvido:\n• Si añadió una rakʿa: se sienta en cuanto se acuerda, hace el tashahhud, se postra y saluda.\n• Si saludó antes de terminar y se acuerda al poco: completa la oración y se postra antes del salām.\n• Hablar un poco por olvido no invalida la oración, y se postra por ello.\n• En la duda: cuenta lo seguro y se postra antes del salām."),
 'hanbali': ("• إِنْ زَادَ رَكْعَةً: يَجْلِسُ مَتَى تَذَكَّرَ، وَيَتَشَهَّدُ إِنْ لَمْ يَكُنْ تَشَهَّدَ، وَيَسْجُدُ قَبْلَ السَّلَامِ.\n• إِنْ سَلَّمَ قَبْلَ تَمَامِهَا وَتَذَكَّرَ قَرِيبًا: يُكْمِلُ وَيَسْجُدُ بَعْدَ السَّلَامِ.\n• فِي الشَّكِّ: يَبْنِي الْمُنْفَرِدُ عَلَى الْيَقِينِ وَيَسْجُدُ قَبْلَ السَّلَامِ، وَالْإِمَامُ يَعْمَلُ بِغَالِبِ ظَنِّهِ وَيَسْجُدُ بَعْدَ السَّلَامِ.",
            "• Si añadió una rakʿa: se sienta en cuanto se acuerda, hace el tashahhud si no lo había hecho y se postra antes del salām.\n• Si saludó antes de terminar y se acuerda al poco: completa la oración y se postra después del salām.\n• En la duda: quien reza solo cuenta lo seguro y se postra antes del salām; el imam sigue lo más probable y se postra después del salām."),
},
'نِسْيَانُ رُكْنٍ (فَرْضٍ)': {
 'hanafi': ("إِذَا تَرَكَ سَجْدَةً سَهْوًا قَضَاهَا مَتَى تَذَكَّرَهَا قَبْلَ السَّلَامِ، وَلَوْ فِي آخِرِ الصَّلَاةِ، وَلَا تَبْطُلُ الرَّكْعَةُ، ثُمَّ يَسْجُدُ لِلسَّهْوِ بَعْدَ السَّلَامِ. أَمَّا إِذَا تَرَكَ الرُّكُوعَ فَلَا يُعْتَدُّ بِالسُّجُودِ الَّذِي بَعْدَهُ حَتَّى يَرْكَعَ.",
            "Si omitió una postración por olvido, la hace cuando se acuerde antes del salām, aunque sea al final de la oración; la rakʿa no se anula, y hace la postración del olvido después del salām. Si omitió la inclinación, la postración que vino después no cuenta hasta que se incline."),
 'shafii': ("إِنْ تَذَكَّرَ الرُّكْنَ قَبْلَ أَنْ يَصِلَ إِلَى مِثْلِهِ مِنَ الرَّكْعَةِ التَّالِيَةِ: عَادَ إِلَيْهِ فَأَتَى بِهِ وَبِمَا بَعْدَهُ. وَإِنْ وَصَلَ إِلَى مِثْلِهِ: تَمَّتْ بِهِ الرَّكْعَةُ الْأُولَى وَلَغَا مَا بَيْنَهُمَا، وَيَأْتِي بِرَكْعَةٍ فِي آخِرِ صَلَاتِهِ، وَيَسْجُدُ قَبْلَ السَّلَامِ.",
            "Si se acuerda del pilar antes de llegar al mismo pilar en la rakʿa siguiente: vuelve a él y lo hace junto con lo que va después. Si ya llegó a ese mismo pilar: con él se completa la rakʿa anterior, lo que hay en medio no cuenta, añade una rakʿa al final y se postra antes del salām."),
 'hanbali': ("إِنْ تَذَكَّرَ الرُّكْنَ قَبْلَ أَنْ يَشْرَعَ فِي قِرَاءَةِ الرَّكْعَةِ التَّالِيَةِ: عَادَ إِلَيْهِ فَأَتَى بِهِ وَبِمَا بَعْدَهُ. وَإِنْ شَرَعَ فِي قِرَاءَتِهَا: بَطَلَتِ الرَّكْعَةُ الَّتِي تَرَكَهُ مِنْهَا، وَقَامَتِ الَّتِي بَعْدَهَا مَقَامَهَا، وَيَسْجُدُ قَبْلَ السَّلَامِ.",
            "Si se acuerda del pilar antes de empezar la recitación de la rakʿa siguiente: vuelve a él y lo hace junto con lo que va después. Si ya empezó a recitar: la rakʿa en la que lo omitió se anula, la siguiente ocupa su lugar y se postra antes del salām."),
},
'إِذَا نَسِيتَ التَّشَهُّدَ الْأَوَّلَ وَقُمْتَ': {
 'hanafi': ("يَعُودُ إِلَى الْجُلُوسِ مَا دَامَ أَقْرَبَ إِلَى الْقُعُودِ، وَلَا سُجُودَ عَلَيْهِ عَلَى الصَّحِيحِ. فَإِنْ صَارَ أَقْرَبَ إِلَى الْقِيَامِ لَمْ يَعُدْ، وَيَسْجُدُ لِلسَّهْوِ بَعْدَ السَّلَامِ.",
            "Vuelve a sentarse mientras esté más cerca de estar sentado, y según la opinión correcta no hay postración. Si ya está más cerca de estar de pie, no vuelve y se postra por el olvido después del salām."),
 'shafii': ("إِنْ لَمْ يَنْتَصِبْ قَائِمًا عَادَ إِلَى الْجُلُوسِ. وَإِنِ انْتَصَبَ قَائِمًا لَمْ يَجُزْ لَهُ الرُّجُوعُ، فَإِنْ عَادَ عَامِدًا عَالِمًا بِالتَّحْرِيمِ بَطَلَتْ صَلَاتُهُ. وَيَسْجُدُ قَبْلَ السَّلَامِ.",
            "Si aún no se ha puesto de pie del todo, vuelve a sentarse. Si ya se puso de pie, no puede volver; si vuelve a propósito sabiendo que está prohibido, la oración se invalida. Se postra antes del salām."),
 'hanbali': ("إِنْ لَمْ يَسْتَتِمَّ قَائِمًا رَجَعَ إِلَى الْجُلُوسِ. وَإِنِ اسْتَتَمَّ قَائِمًا كُرِهَ رُجُوعُهُ، وَإِنْ شَرَعَ فِي الْقِرَاءَةِ حَرُمَ عَلَيْهِ الرُّجُوعُ. وَيَسْجُدُ قَبْلَ السَّلَامِ.",
            "Si aún no se ha puesto de pie del todo, vuelve a sentarse. Si ya se puso de pie, volver es desaconsejado, y si empezó a recitar, prohibido. Se postra antes del salām."),
},
'الْقَاعِدَةُ: قَضَاءُ الْقَوْلِ وَبِنَاءُ الْفِعْلِ': {
 'hanafi': ("مَا يَقْضِيهِ الْمَسْبُوقُ هُوَ أَوَّلُ صَلَاتِهِ فِي حَقِّ الْقِرَاءَةِ، فَيَقْرَأُ فِيهِ الْفَاتِحَةَ وَسُورَةً، وَآخِرُهَا فِي حَقِّ التَّشَهُّدِ، فَيَجْلِسُ عَلَى حَسَبِ مَا أَدْرَكَ. وَهُوَ قَرِيبٌ مِنْ قَوْلِ الْمَالِكِيَّةِ.",
            "Lo que recupera quien llega tarde es el principio de su oración en cuanto a la recitación, así que recita Al-Fātiḥa y una sura; y es el final en cuanto al tashahhud, así que se sienta según lo que alcanzó. Es parecido a la postura malikí."),
 'shafii': ("مَا أَدْرَكَهُ الْمَسْبُوقُ مَعَ الْإِمَامِ هُوَ أَوَّلُ صَلَاتِهِ، وَمَا يَقْضِيهِ آخِرُهَا. فَإِذَا أَدْرَكَ رَكْعَتَيْنِ مِنَ الرُّبَاعِيَّةِ أَتَى بِرَكْعَتَيْنِ بِالْفَاتِحَةِ، وَيُسْتَحَبُّ أَنْ يَقْرَأَ السُّورَةَ فِيهِمَا إِنْ فَاتَتْهُ مَعَ الْإِمَامِ.",
            "Lo que alcanzó con el imam es el principio de su oración, y lo que recupera es el final. Si alcanzó dos rakʿas de una oración de cuatro, reza dos rakʿas con Al-Fātiḥa, y es recomendable añadir la sura si no la pudo recitar con el imam."),
 'hanbali': ("مَا أَدْرَكَهُ الْمَسْبُوقُ آخِرُ صَلَاتِهِ، وَمَا يَقْضِيهِ أَوَّلُهَا: يَسْتَفْتِحُ وَيَتَعَوَّذُ وَيَقْرَأُ الْفَاتِحَةَ وَسُورَةً. لَكِنْ إِذَا أَدْرَكَ رَكْعَةً مِنَ الْمَغْرِبِ أَوِ الرُّبَاعِيَّةِ تَشَهَّدَ عَقِبَ قَضَاءِ رَكْعَةٍ.",
            "Lo que alcanzó es el final de su oración y lo que recupera es el principio: hace la súplica de apertura, el taʿawwudh y recita Al-Fātiḥa y una sura. Pero si alcanzó una rakʿa del Maghrib o de una oración de cuatro, hace el tashahhud después de recuperar una rakʿa."),
},
'الْمَسْبُوقُ وَسُجُودُ السَّهْوِ': {
 'hanafi': ("يَسْجُدُ الْمَسْبُوقُ مَعَ إِمَامِهِ بَعْدَ سَلَامِهِ (وَلَا يُسَلِّمُ مَعَهُ)، ثُمَّ يَقُومُ لِيَقْضِيَ مَا فَاتَهُ.",
            "Quien llega tarde se postra con su imam después del salām de este (sin saludar con él), y luego se levanta a recuperar lo que le faltó."),
 'shafii': ("يَسْجُدُ الْمَسْبُوقُ مَعَ إِمَامِهِ، ثُمَّ يُعِيدُ السُّجُودَ فِي آخِرِ صَلَاتِهِ قَبْلَ سَلَامِهِ.",
            "Quien llega tarde se postra con su imam, y vuelve a hacer la postración al final de su oración, antes de su salām."),
 'hanbali': ("إِنْ سَجَدَ الْإِمَامُ قَبْلَ السَّلَامِ سَجَدَ الْمَسْبُوقُ مَعَهُ، ثُمَّ قَامَ لِيَقْضِيَ. وَإِنْ سَجَدَ بَعْدَ السَّلَامِ قَامَ لِيَقْضِيَ، ثُمَّ سَجَدَ بَعْدَ سَلَامِهِ.",
            "Si el imam se postra antes del salām, quien llega tarde se postra con él y luego se levanta a recuperar. Si se postra después del salām, se levanta a recuperar y se postra después de su propio salām."),
},
}
